<?php
require __DIR__.'/../config/config.php'; require_admin();
$action=$_GET['action']??'';$id=(int)($_GET['id']??0);$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)$_POST['id'];$v=[trim($_POST['school']),trim($_POST['name']),trim($_POST['level']),trim($_POST['description']),$_POST['status']];if($id){$s=db()->prepare("UPDATE courses SET school=?,name=?,level=?,description=?,status=? WHERE id=?");$s->execute([$v[0],$v[1],$v[2],$v[3],$v[4],$id]);}else{$s=db()->prepare("INSERT INTO courses(school,name,level,description,status) VALUES(?,?,?,?,?)");$s->execute($v);}$msg='Course saved.';$action='';}
if($action==='delete'&&$id){$s=db()->prepare("DELETE FROM courses WHERE id=?");$s->execute([$id]);header('Location:courses.php');exit;}
$edit=$id?db()->prepare("SELECT * FROM courses WHERE id=?"):null;if($edit){$edit->execute([$id]);$row=$edit->fetch();}else{$row=['id'=>0,'school'=>'','name'=>'','level'=>'UG','description'=>'','status'=>'active'];}
$rows=db()->query("SELECT * FROM courses ORDER BY school,name")->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Courses</title><link rel="stylesheet" href="admin.css"></head><body><div class="layout"><aside class="side"><h2>GBU ADMIN</h2><a href="index.php">Dashboard</a><a href="notices.php">Notices</a><a class="active" href="courses.php">Courses</a><a href="events.php">Events</a><a href="admins.php">Admins</a><a href="logout.php">Logout</a></aside><main class="main"><div class="top"><h1>Courses</h1><a class="button gold" href="?action=new">+ New</a></div><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><?php if($action==='new'||$id):?><div class="panel"><h2><?= $id?'Edit':'Add' ?> Course</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$row['id']?>"><label>School</label><input name="school" required value="<?=e($row['school'])?>"><label>Programme Name</label><input name="name" required value="<?=e($row['name'])?>"><div class="formgrid"><div><label>Level</label><select name="level"><option>UG</option><option>PG</option><option>PhD</option><option>Diploma</option></select></div><div><label>Status</label><select name="status"><option value="active">Active</option><option value="inactive">Inactive</option></select></div></div><label>Description</label><textarea name="description" rows="4"><?=e($row['description'])?></textarea><button class="button gold">Save</button> <a class="button" href="courses.php">Cancel</a></form></div><?php endif;?><div class="panel"><table class="table"><tr><th>School</th><th>Programme</th><th>Level</th><th>Status</th><th>Actions</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['school'])?></td><td><?=e($r['name'])?></td><td><?=e($r['level'])?></td><td><?=e($r['status'])?></td><td><a class="button" href="?id=<?=$r['id']?>">Edit</a> <a class="button danger" onclick="return confirm('Delete?')" href="?action=delete&id=<?=$r['id']?>">Delete</a></td></tr><?php endforeach;?></table></div></main></div></body></html>